const hud={seeds:$('#seeds'),water:$('#waterBar'),wrap:$('#waterWrap'),depth:$('#depth'),sack:$('#sack'),onions:$('#onions'),tools:$('#tools'),det:$('#detector'),sig:$('#sigBar'),prompt:$('#prompt')};
let hudT=0,lastTools='';
